// ─── File: RecoverabilityDemo.java ───
// Shows: atomic single-store transfer (idempotent) + eventual consistency via reconciliation,
// WITHOUT any distributed/2PC transaction across DB and Kafka.
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class RecoverabilityDemo {
    private static final Logger log = Logger.getLogger("Recover");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Ledger ledger = new Ledger();
        EventStore events = new EventStore();
        TransferService service = new TransferService(ledger, events);

        BigDecimal rentAmount = new BigDecimal("50000");

        // Transfer 1: fully succeeds — atomic ledger write + event recorded.
        service.transfer("TXN-1", "SAV2001", "CUR3001", rentAmount);

        // Safe retry: same txn id replays harmlessly (idempotent).
        log.info("--- retry same TXN-1 (should be a no-op) ---");
        service.transfer("TXN-1", "SAV2001", "CUR3001", rentAmount);

        // Transfer 2: ledger commits but the event is LOST (process crashed after DB commit).
        log.info("--- TXN-2 commits in ledger but event is lost ---");
        service.transferLedgerOnly("TXN-2", "SAV2001", "CUR3001", new BigDecimal("10000"));

        // Reconciliation finds TXN-2 has no event and repairs it — eventual consistency.
        log.info("--- nightly reconciliation ---");
        Reconciler reconciler = new Reconciler(ledger, events);
        reconciler.reconcile();
    }
}

// ─── Would be in model/TransferRecord.java ───
class TransferRecord {
    final String txnId, fromId, toId; final BigDecimal amount;
    TransferRecord(String txnId, String fromId, String toId, BigDecimal amount) {
            this.txnId = txnId;
            this.fromId = fromId
            this.toId = toId
            this.amount = amount;
    }
}

// ─── Would be in model/DomainEvent.java ───
class DomainEvent {
    final UUID eventId = UUID.randomUUID(); final String txnId, type;
        DomainEvent(String txnId, String type) { this.txnId = txnId;
        this.type = type; }
}

// ─── Would be in repository/Ledger.java ───
class Ledger {
    private static final Logger log = Logger.getLogger("Recover");
    private final Map<String, BigDecimal> balances = new HashMap<>();
    private final Map<String, TransferRecord> transfers = new LinkedHashMap<>();
    Ledger() { balances.put("SAV2001", new BigDecimal("1000000")); balances.put("CUR3001", new BigDecimal("250000")); }

    // ONE local transaction: debit + credit + transfer record, atomic by construction.
    // Idempotent: same txnId applied twice is a no-op (safe retry).
    synchronized void applyTransfer(String txnId, String fromId, String toId, BigDecimal amt) {
        if (transfers.containsKey(txnId)) {
            log.warning(() -> "TXN " + txnId + " already applied — no-op (idempotent)");
            return;
        }
        BigDecimal from = balances.get(fromId);
        if (from.compareTo(amt) < 0) throw new IllegalStateException("Insufficient funds");
        balances.put(fromId, from.subtract(amt));
        balances.put(toId, balances.get(toId).add(amt));
        transfers.put(txnId, new TransferRecord(txnId, fromId, toId, amt));
        log.info(() -> "Ledger committed " + txnId + " amount " + amt
                + " (atomic single-store debit+credit)");
    }
    Collection<TransferRecord> allTransfers() { return transfers.values(); }
}

// ─── Would be in repository/EventStore.java ───
class EventStore {
    private final List<DomainEvent> events = new ArrayList<>();
    void record(DomainEvent e) { events.add(e); }
    boolean hasEventFor(String txnId) {
        return events.stream().anyMatch(e -> e.txnId.equals(txnId));
    }
}

// ─── Would be in service/TransferService.java ───
class TransferService {
    private static final Logger log = Logger.getLogger("Recover");
    private final Ledger ledger; private final EventStore events;
        TransferService(Ledger ledger, EventStore events) { this.ledger = ledger;
        this.events = events; }

    void transfer(String txnId, String fromId, String toId, BigDecimal amt) {
        ledger.applyTransfer(txnId, fromId, toId, amt);        // durable local TX (atomic)
        events.record(new DomainEvent(txnId, "TransferCompleted")); // separate durable write
        log.info(() -> "Event recorded for " + txnId);
    }
    // Simulate: DB commits but process dies before the event is durably recorded.
    void transferLedgerOnly(String txnId, String fromId, String toId, BigDecimal amt) {
        ledger.applyTransfer(txnId, fromId, toId, amt);
        log.warning(() -> "Process died before recording event for " + txnId);
    }
}

// ─── Would be in service/Reconciler.java ───
class Reconciler {
    private static final Logger log = Logger.getLogger("Recover");
    private final Ledger ledger; private final EventStore events;
        Reconciler(Ledger ledger, EventStore events) { this.ledger = ledger;
        this.events = events; }
    // Compare the two durable stores and repair gaps — eventual consistency, no 2PC.
    void reconcile() {
        for (TransferRecord t : ledger.allTransfers()) {
            if (!events.hasEventFor(t.txnId)) {
                events.record(new DomainEvent(t.txnId, "TransferCompleted"));
                log.info(() -> "Reconciler repaired missing event for " + t.txnId);
            }
        }
        log.info("Reconciliation complete — ledger and events consistent.");
    }
}

// ─── Would be in config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
